import{_ as o,h as r,i as e,c as n,v as l,p as s,x as i,m as E,e as h,S as p}from"./chunks/framework.Dvtg8yj2.js";const f=JSON.parse('{"title":"HELM 多维度评测","description":"","frontmatter":{"title":"HELM 多维度评测","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/helm.md","filePath":"llm/helm.md","lastUpdated":1788454257000}'),d={name:"llm/helm.md"};function m(c,a,A,u,_,g){const t=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="helm-多维度评测" tabindex="-1">HELM 多维度评测 <a class="header-anchor" href="#helm-多维度评测" aria-label="Permalink to &quot;HELM 多维度评测&quot;">​</a></h1><div class="epigraph"><p>准确率只是一张成绩单上的一栏。校准、鲁棒、公平、偏见、毒性、效率若不一起报，模型比较就是在用不同的尺子各说各话。</p><footer>—— Liang et al., Holistic Evaluation of Language Models</footer></div><p>排行榜喜欢一个数。部署关心一束性质：在目标场景上是否够准，错的时候是否知道自己错，输入扰动后是否崩，对哪些人群系统性更差，是否更容易吐出有害内容，以及单位美元能服务多少请求。Liang 等人提出 HELM（Holistic Evaluation of Language Models），把评测写成场景 × 指标的矩阵：先规定用哪些用例（问答、摘要、分类、信息检索等），再在每个用例上用同一套多指标协议跑一组模型，强调透明的提示、规范化与成本。它不是又一份更难的题库，而是一种记账法——反对用 MMLU 一个点去代表语言模型。本篇讲矩阵怎么搭、为什么「全面」仍会漏项，以及如何避免把 HELM 缩回单列准确率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单一基准的激励是扭曲的。优化 GSM8K 不会自动改善校准；优化聊天arena 的偏好，可能提高讨好性同时降低诚实性。实验室若只对外公布自己领先的那一列，社区无法判断权衡。另一方面，指标若完全不统一——有人报 F1，有人报 Rouge，有人报人工胜率——模型之间不可比。需要一个公共账本：场景有限但明示，指标固定，所有模型走同一提示与解码默认值，结果以原始预测归档，便于事后加新指标。</p><p>HELM 还针对「评测即广告」：许多报告不写提示、不写截断、不写是否用了思维链或工具。换一个模板，名次就能换。多维度评测若没有标准化适配层，多指标只是把不可复现放大了七倍。问题因此是双重的：量什么，以及在何种冻结协议下量。</p><h3 id="场景先于模型家族" tabindex="-1">场景先于模型家族 <a class="header-anchor" href="#场景先于模型家族" aria-label="Permalink to &quot;场景先于模型家族&quot;">​</a></h3><p>先选用户真正会做的事（追问事实、摘要合同、分类工单），再让各家模型来适配，而不是为某个模型的上下文长度或函数调用特长去定制场景。这会让擅长闲聊的模型在分类上难看，也是目的：holism 不是「每个模型都有高分项」，而是同一张表上的剖面。场景太少会回到单一基准；太多则没人跑完。HELM 的取舍是覆盖主要用例与若干风险相关任务，而不是穷尽所有学科竞赛。<span class="marginnote">把 HELM 理解成「斯坦福的排行榜」会用错。它的可引用价值是协议：场景清单、指标定义、适配规范、公开预测。自己的业务评测可以复用这套记账，不必原样复跑当年那一张模型表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="场景-×-指标矩阵" tabindex="-1">场景 × 指标矩阵 <a class="header-anchor" href="#场景-×-指标矩阵" aria-label="Permalink to &quot;场景 × 指标矩阵&quot;">​</a></h3><p>对每个场景 \\(s\\)，至少报：</p><ul><li><strong>准确类</strong>：精确匹配、F1、任务特定准确率。</li><li><strong>校准</strong>：置信度与对错是否对齐，例如期望校准误差。</li><li><strong>鲁棒</strong>：对同义改写、大小写、噪声的性能跌幅。</li><li><strong>公平 / 偏见</strong>：切片准确率差距、刻板联想。</li><li><strong>毒性 / 安全</strong>：有害续写率、拒答是否过度。</li><li><strong>效率</strong>：参数量、延迟、美元成本、碳排放的粗代理。</li></ul> \\[\\mathrm{Report}(M)=\\bigl\\{\\,m_k(M,s):k\\in K,\\ s\\in S\\,\\bigr\\} \\]<p>没有合法的「HELM 总分」除非预先公布权重向量 \\(w_k\\)。默认应展示矩阵或雷达，需要门禁时由产品自己定义 \\(w\\)，并承认那是价值判断而不是科学发现。</p><p>适配层规定：每个模型如何被包成同一接口（补全还是对话）、最大生成长度、温度、是否少样本。少样本样例来自场景的开发切分，避免测试泄漏。预测全文落地，使后来的毒性分类器升级时不必重跑生成——这是多指标评测能持续的关键工程。</p>',15)),(e(),s(p,null,{default:i(()=>[h(t,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%9C%BA%E6%99%AF%E9%9B%86%E5%90%88%20S%22%5D%20--%3E%20A%5B%22%E7%BB%9F%E4%B8%80%E9%80%82%E9%85%8D%20%2F%20%E6%8F%90%E7%A4%BA%22%5D%0A%20%20M%5B%22%E6%A8%A1%E5%9E%8B%E9%9B%86%E5%90%88%22%5D%20--%3E%20A%0A%20%20A%20--%3E%20P%5B%22%E5%BD%92%E6%A1%A3%E5%8E%9F%E5%A7%8B%E9%A2%84%E6%B5%8B%22%5D%0A%20%20P%20--%3E%20K1%5B%22%E5%87%86%E7%A1%AE%22%5D%0A%20%20P%20--%3E%20K2%5B%22%E6%A0%A1%E5%87%86%22%5D%0A%20%20P%20--%3E%20K3%5B%22%E9%B2%81%E6%A3%92%22%5D%0A%20%20P%20--%3E%20K4%5B%22%E5%85%AC%E5%B9%B3%20%2F%20%E6%AF%92%E6%80%A7%22%5D%0A%20%20P%20--%3E%20K5%5B%22%E6%95%88%E7%8E%87%22%5D%0A%20%20K1%20--%3E%20R%5B%22%E5%89%96%E9%9D%A2%E6%8A%A5%E5%91%8A%22%5D%0A%20%20K2%20--%3E%20R%0A%20%20K3%20--%3E%20R%0A%20%20K4%20--%3E%20R%0A%20%20K5%20--%3E%20R%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="透明比「我们测了七个指标」更重要" tabindex="-1">透明比「我们测了七个指标」更重要 <a class="header-anchor" href="#透明比「我们测了七个指标」更重要" aria-label="Permalink to &quot;透明比「我们测了七个指标」更重要&quot;">​</a></h3><p>HELM 论文把提示模板、规范化步骤和评估代码公开，使争议可以落到具体字符串。这与只报一个 Arena Elo 不同：Elo 聚合了不可见的投票与对手匹配。多维度评测若闭源，外部无法检查某个公平切片是否样本量为 12。方法的一部分就是发布：题目版本、切片定义、预测文件。缺这些，多指标只是更长的新闻稿。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>准确率不传递校准。模型可以把概率质量集中在错误选项上而看起来很自信；在部署里，这比「温和地答错」更糟。HELM 强制在同一批预测上算校准，使「高分但胡乱自信」变得可见。鲁棒指标针对的是另一种捷径：对基准分布过拟合的表面相关，换一种措辞就掉点。公平切片则防止总分被多数群体托起。毒性测的是生成分布的尾部，和选择题准确率几乎正交——这也是为什么单一 MMLU 分无法代理安全。</p><p>效率进入矩阵，是为了打断「只比最大模型」的竞赛。一个小模型若在目标场景上够用且便宜一个数量级，holistic 比较应显示这一点，而不是把它排除在「前沿」之外。成本数字会过时，但把成本当作一等指标的做法不过时。</p><h3 id="指标之间会打架-这是特征" tabindex="-1">指标之间会打架，这是特征 <a class="header-anchor" href="#指标之间会打架-这是特征" aria-label="Permalink to &quot;指标之间会打架，这是特征&quot;">​</a></h3><p>提高召回可能提高毒性命中；加强拒答可能伤害可用性；对抗鲁棒的训练可能降一点干净准确率。矩阵把权衡留在纸面，逼决策者选，而不是让平均分替他们选。若事后发明一个加权总分把某模型送上头条，等于把 holism 折叠回去。内部可以用加权做发布门禁，对外仍应给剖面。<span class="marginnote">校准差的高准确率，在 GPQA 这类专家题上特别危险：用户会把流畅的错误推导当成领域结论。HELM 的校准栏与 <a href="/llm/mmlu-pro-gpqa">MMLU-Pro / GPQA</a> 一起读，比单独刷准确率有用。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>「全面」是相对当年场景清单而言。智能体修仓库、多模态、长上下文、工具调用，在早期 HELM 里不是一等场景。补这些不应破坏矩阵思想：新场景进 \\(S\\)，新指标进 \\(K\\)，旧预测能留的留。不要每出一种产品形态就另起一个互不兼容的总分榜。</p><p>多指标增加评测成本与解释成本。跑完准确率再跑毒性分类器、公平切片、多种扰动，生成次数乘起来。实务分层：提交门禁用准确 + 毒性冒烟，发布前跑全矩阵，研究论文按问题选列。假装每次 git push 都跑 holistic，只会导致指标被抽稀到无意义。</p><p>切片公平对样本量极度敏感。某个人口组只有几十条，差距的置信区间可以吞掉点估计。报告必须写 \\(n\\) 与区间，避免用不可靠切片做宣传或自我开脱。毒性分类器自身有偏见，用它当指标会循环；应定期用人工校准分类器，并归档版本。</p><p>与<a href="/llm/live-benchmarks">动态基准</a>兼容：矩阵的行可以随时间换题，列保持不变。这样「这个月准确率上升、校准变差」是可解释的趋势。与 <a href="/llm/bigbench-bbh">BIG-bench</a> 的差别是：BIG-bench 扩展的是行（任务种类），HELM 扩展的是列（同一任务上的性质）。两者都反对单数字，但压缩方式不同。</p><p>静态场景仍会污染。HELM 不自动提供时间切分；事实类场景应搭配 <a href="/llm/simpleqa-freshqa">SimpleQA / FreshQA</a> 或内部新题。效率数字依赖硬件与批大小，跨实验室比较时只能当数量级，不能当精确排名。<span class="marginnote">同一场景上换解码温度，准确率、毒性、校准会一起动。矩阵比较必须冻结温度与 <code>max_tokens</code>，否则「更安全」可能只是更短、更拒答。效率列若用单请求延迟，还要声明批大小，否则小模型的吞吐优势看不见。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HELM 把评测写成场景 × 指标矩阵，反对用单一准确率代表语言模型。</li><li>标准化适配、公开提示与归档预测，是多维度可复现的前提。</li><li>校准、鲁棒、公平、毒性、效率与准确率往往正交，权衡应留在剖面里。</li><li>不存在中立的 HELM 总分；加权是价值选择，须预先声明。</li><li>场景清单会过时，矩阵结构可以沿用到智能体与多模态。</li><li>切片样本量、毒性分类器版本、成本度量都是一等误差源。</li><li>出处：Liang et al., <em>Holistic Evaluation of Language Models</em>。</li></ul>',15))])}const b=o(d,[["render",m]]);export{f as __pageData,b as default};
